-- Ensina-me: deepen Gestão Escolar, Coordenação Pedagógica, Legislação and Políticas Públicas.
-- Idempotent content migration.

update public.material_sections ms
set content=v.content,updated_at=now()
from (values
($$Gestão Escolar$$,$$Concepções de gestão escolar$$,1,$$O ponto central de concepções de gestão escolar é distinguir administrar recursos de coordenar decisões que afetam o ensino e a aprendizagem. A compreensão começa por reconhecer quais decisões, relações e evidências fazem esse tema funcionar no cotidiano educacional.$$),
($$Gestão Escolar$$,$$Concepções de gestão escolar$$,2,$$Esse tema ganha sentido quando observado no contexto da escola e das políticas educacionais. Aqui, vale perguntar como reduzir a escola à burocracia e deixar objetivos pedagógicos em segundo plano aparece em situações concretas e quem participa das decisões.$$),
($$Gestão Escolar$$,$$Concepções de gestão escolar$$,3,$$Os conceitos principais precisam ser relacionados entre si. Em concepções de gestão escolar, isso significa analisar a relação entre objetivos educacionais, responsabilidades, práticas profissionais e condições institucionais.$$),
($$Gestão Escolar$$,$$Concepções de gestão escolar$$,4,$$Um exemplo ajuda a visualizar a ideia: imagine uma escola diante de um problema de aprendizagem ou organização. A resposta precisa considerar reduzir a escola à burocracia e deixar objetivos pedagógicos em segundo plano, e não apenas uma ação isolada de um único profissional.$$),
($$Gestão Escolar$$,$$Concepções de gestão escolar$$,5,$$Na análise de uma situação real, procure identificar atores, responsabilidades, recursos, informações disponíveis e efeitos das decisões. Esse olhar evita conclusões rápidas sobre concepções de gestão escolar.$$),
($$Gestão Escolar$$,$$Concepções de gestão escolar$$,6,$$Um erro frequente é undefined. Quando isso acontece, o conceito perde sua função analítica e a prática passa a responder mais a rotinas ou aparências do que às finalidades educacionais.$$),
($$Gestão Escolar$$,$$Concepções de gestão escolar$$,7,$$O aprofundamento pede atenção às relações entre norma, planejamento, prática e acompanhamento. Nenhuma dessas dimensões explica sozinha concepções de gestão escolar; o sentido aparece na articulação entre elas.$$),
($$Gestão Escolar$$,$$Concepções de gestão escolar$$,8,$$Na prática pedagógica, uma boa aplicação é transformar o conceito em procedimento observável: definir uma questão, reunir evidências, discutir alternativas, decidir responsabilidades e acompanhar o que mudou depois da ação.$$),
($$Gestão Escolar$$,$$Concepções de gestão escolar$$,9,$$A síntese pode ser feita em uma sequência: finalidade educativa, atores envolvidos, decisões necessárias, evidências usadas e critérios de acompanhamento. Essa estrutura torna concepções de gestão escolar mais fácil de estudar e aplicar.$$),
($$Gestão Escolar$$,$$Concepções de gestão escolar$$,10,$$Para revisar, tente explicar concepções de gestão escolar sem consultar o material e depois dê um exemplo de situação escolar em que reduzir a escola à burocracia e deixar objetivos pedagógicos em segundo plano. Se a explicação depender apenas de palavras-chave, retome os conceitos e suas relações.$$),
($$Gestão Escolar$$,$$Gestão democrática$$,1,$$O ponto central de gestão democrática é entender como decisões e responsabilidades podem ser compartilhadas na comunidade escolar. A compreensão começa por reconhecer quais decisões, relações e evidências fazem esse tema funcionar no cotidiano educacional.$$),
($$Gestão Escolar$$,$$Gestão democrática$$,2,$$Esse tema ganha sentido quando observado no contexto da escola e das políticas educacionais. Aqui, vale perguntar como confundir participação simbólica com participação efetiva nas decisões aparece em situações concretas e quem participa das decisões.$$),
($$Gestão Escolar$$,$$Gestão democrática$$,3,$$Os conceitos principais precisam ser relacionados entre si. Em gestão democrática, isso significa analisar a relação entre objetivos educacionais, responsabilidades, práticas profissionais e condições institucionais.$$),
($$Gestão Escolar$$,$$Gestão democrática$$,4,$$Um exemplo ajuda a visualizar a ideia: imagine uma escola diante de um problema de aprendizagem ou organização. A resposta precisa considerar confundir participação simbólica com participação efetiva nas decisões, e não apenas uma ação isolada de um único profissional.$$),
($$Gestão Escolar$$,$$Gestão democrática$$,5,$$Na análise de uma situação real, procure identificar atores, responsabilidades, recursos, informações disponíveis e efeitos das decisões. Esse olhar evita conclusões rápidas sobre gestão democrática.$$),
($$Gestão Escolar$$,$$Gestão democrática$$,6,$$Um erro frequente é undefined. Quando isso acontece, o conceito perde sua função analítica e a prática passa a responder mais a rotinas ou aparências do que às finalidades educacionais.$$),
($$Gestão Escolar$$,$$Gestão democrática$$,7,$$O aprofundamento pede atenção às relações entre norma, planejamento, prática e acompanhamento. Nenhuma dessas dimensões explica sozinha gestão democrática; o sentido aparece na articulação entre elas.$$),
