($$Políticas Públicas Educacionais$$,$$Estado, política e direito à educação$$,10,$$Para revisar, tente explicar estado, política e direito à educação sem consultar o material e depois dê um exemplo de situação escolar em que descrever política apenas pelo programa anunciado, sem analisar implementação e efeitos. Se a explicação depender apenas de palavras-chave, retome os conceitos e suas relações.$$),
($$Políticas Públicas Educacionais$$,$$Políticas educacionais brasileiras$$,1,$$O ponto central de políticas educacionais brasileiras é relacionar políticas a contextos históricos, problemas públicos e capacidades institucionais. A compreensão começa por reconhecer quais decisões, relações e evidências fazem esse tema funcionar no cotidiano educacional.$$),
($$Políticas Públicas Educacionais$$,$$Políticas educacionais brasileiras$$,2,$$Esse tema ganha sentido quando observado no contexto da escola e das políticas educacionais. Aqui, vale perguntar como tratar políticas diferentes como se fossem equivalentes apenas por atuarem na mesma etapa aparece em situações concretas e quem participa das decisões.$$),
($$Políticas Públicas Educacionais$$,$$Políticas educacionais brasileiras$$,3,$$Os conceitos principais precisam ser relacionados entre si. Em políticas educacionais brasileiras, isso significa analisar a relação entre objetivos educacionais, responsabilidades, práticas profissionais e condições institucionais.$$),
($$Políticas Públicas Educacionais$$,$$Políticas educacionais brasileiras$$,4,$$Um exemplo ajuda a visualizar a ideia: imagine uma escola diante de um problema de aprendizagem ou organização. A resposta precisa considerar tratar políticas diferentes como se fossem equivalentes apenas por atuarem na mesma etapa, e não apenas uma ação isolada de um único profissional.$$),
($$Políticas Públicas Educacionais$$,$$Políticas educacionais brasileiras$$,5,$$Na análise de uma situação real, procure identificar atores, responsabilidades, recursos, informações disponíveis e efeitos das decisões. Esse olhar evita conclusões rápidas sobre políticas educacionais brasileiras.$$),
($$Políticas Públicas Educacionais$$,$$Políticas educacionais brasileiras$$,6,$$Um erro frequente é undefined. Quando isso acontece, o conceito perde sua função analítica e a prática passa a responder mais a rotinas ou aparências do que às finalidades educacionais.$$),
($$Políticas Públicas Educacionais$$,$$Políticas educacionais brasileiras$$,7,$$O aprofundamento pede atenção às relações entre norma, planejamento, prática e acompanhamento. Nenhuma dessas dimensões explica sozinha políticas educacionais brasileiras; o sentido aparece na articulação entre elas.$$),
($$Políticas Públicas Educacionais$$,$$Políticas educacionais brasileiras$$,8,$$Na prática pedagógica, uma boa aplicação é transformar o conceito em procedimento observável: definir uma questão, reunir evidências, discutir alternativas, decidir responsabilidades e acompanhar o que mudou depois da ação.$$),
($$Políticas Públicas Educacionais$$,$$Políticas educacionais brasileiras$$,9,$$A síntese pode ser feita em uma sequência: finalidade educativa, atores envolvidos, decisões necessárias, evidências usadas e critérios de acompanhamento. Essa estrutura torna políticas educacionais brasileiras mais fácil de estudar e aplicar.$$),
($$Políticas Públicas Educacionais$$,$$Políticas educacionais brasileiras$$,10,$$Para revisar, tente explicar políticas educacionais brasileiras sem consultar o material e depois dê um exemplo de situação escolar em que tratar políticas diferentes como se fossem equivalentes apenas por atuarem na mesma etapa. Se a explicação depender apenas de palavras-chave, retome os conceitos e suas relações.$$),
($$Políticas Públicas Educacionais$$,$$Financiamento da educação$$,1,$$O ponto central de financiamento da educação é entender por que financiamento influencia condições de funcionamento e possibilidades de política. A compreensão começa por reconhecer quais decisões, relações e evidências fazem esse tema funcionar no cotidiano educacional.$$),
($$Políticas Públicas Educacionais$$,$$Financiamento da educação$$,2,$$Esse tema ganha sentido quando observado no contexto da escola e das políticas educacionais. Aqui, vale perguntar como reduzir financiamento ao valor total gasto sem observar regras, destinatários e desigualdades aparece em situações concretas e quem participa das decisões.$$),
($$Políticas Públicas Educacionais$$,$$Financiamento da educação$$,3,$$Os conceitos principais precisam ser relacionados entre si. Em financiamento da educação, isso significa analisar a relação entre objetivos educacionais, responsabilidades, práticas profissionais e condições institucionais.$$),
($$Políticas Públicas Educacionais$$,$$Financiamento da educação$$,4,$$Um exemplo ajuda a visualizar a ideia: imagine uma escola diante de um problema de aprendizagem ou organização. A resposta precisa considerar reduzir financiamento ao valor total gasto sem observar regras, destinatários e desigualdades, e não apenas uma ação isolada de um único profissional.$$),
($$Políticas Públicas Educacionais$$,$$Financiamento da educação$$,5,$$Na análise de uma situação real, procure identificar atores, responsabilidades, recursos, informações disponíveis e efeitos das decisões. Esse olhar evita conclusões rápidas sobre financiamento da educação.$$),
($$Políticas Públicas Educacionais$$,$$Financiamento da educação$$,6,$$Um erro frequente é undefined. Quando isso acontece, o conceito perde sua função analítica e a prática passa a responder mais a rotinas ou aparências do que às finalidades educacionais.$$),
($$Políticas Públicas Educacionais$$,$$Financiamento da educação$$,7,$$O aprofundamento pede atenção às relações entre norma, planejamento, prática e acompanhamento. Nenhuma dessas dimensões explica sozinha financiamento da educação; o sentido aparece na articulação entre elas.$$),
($$Políticas Públicas Educacionais$$,$$Financiamento da educação$$,8,$$Na prática pedagógica, uma boa aplicação é transformar o conceito em procedimento observável: definir uma questão, reunir evidências, discutir alternativas, decidir responsabilidades e acompanhar o que mudou depois da ação.$$),
($$Políticas Públicas Educacionais$$,$$Financiamento da educação$$,9,$$A síntese pode ser feita em uma sequência: finalidade educativa, atores envolvidos, decisões necessárias, evidências usadas e critérios de acompanhamento. Essa estrutura torna financiamento da educação mais fácil de estudar e aplicar.$$),
($$Políticas Públicas Educacionais$$,$$Financiamento da educação$$,10,$$Para revisar, tente explicar financiamento da educação sem consultar o material e depois dê um exemplo de situação escolar em que reduzir financiamento ao valor total gasto sem observar regras, destinatários e desigualdades. Se a explicação depender apenas de palavras-chave, retome os conceitos e suas relações.$$),
($$Políticas Públicas Educacionais$$,$$Implementação e avaliação de políticas$$,1,$$O ponto central de implementação e avaliação de políticas é acompanhar recursos, atores, capacidades locais e evidências de implementação. A compreensão começa por reconhecer quais decisões, relações e evidências fazem esse tema funcionar no cotidiano educacional.$$),
($$Políticas Públicas Educacionais$$,$$Implementação e avaliação de políticas$$,2,$$Esse tema ganha sentido quando observado no contexto da escola e das políticas educacionais. Aqui, vale perguntar como presumir que uma política produz os mesmos resultados em todos os contextos aparece em situações concretas e quem participa das decisões.$$),
($$Políticas Públicas Educacionais$$,$$Implementação e avaliação de políticas$$,3,$$Os conceitos principais precisam ser relacionados entre si. Em implementação e avaliação de políticas, isso significa analisar a relação entre objetivos educacionais, responsabilidades, práticas profissionais e condições institucionais.$$),
($$Políticas Públicas Educacionais$$,$$Implementação e avaliação de políticas$$,4,$$Um exemplo ajuda a visualizar a ideia: imagine uma escola diante de um problema de aprendizagem ou organização. A resposta precisa considerar presumir que uma política produz os mesmos resultados em todos os contextos, e não apenas uma ação isolada de um único profissional.$$),
($$Políticas Públicas Educacionais$$,$$Implementação e avaliação de políticas$$,5,$$Na análise de uma situação real, procure identificar atores, responsabilidades, recursos, informações disponíveis e efeitos das decisões. Esse olhar evita conclusões rápidas sobre implementação e avaliação de políticas.$$),
($$Políticas Públicas Educacionais$$,$$Implementação e avaliação de políticas$$,6,$$Um erro frequente é undefined. Quando isso acontece, o conceito perde sua função analítica e a prática passa a responder mais a rotinas ou aparências do que às finalidades educacionais.$$),
($$Políticas Públicas Educacionais$$,$$Implementação e avaliação de políticas$$,7,$$O aprofundamento pede atenção às relações entre norma, planejamento, prática e acompanhamento. Nenhuma dessas dimensões explica sozinha implementação e avaliação de políticas; o sentido aparece na articulação entre elas.$$),
($$Políticas Públicas Educacionais$$,$$Implementação e avaliação de políticas$$,8,$$Na prática pedagógica, uma boa aplicação é transformar o conceito em procedimento observável: definir uma questão, reunir evidências, discutir alternativas, decidir responsabilidades e acompanhar o que mudou depois da ação.$$),
($$Políticas Públicas Educacionais$$,$$Implementação e avaliação de políticas$$,9,$$A síntese pode ser feita em uma sequência: finalidade educativa, atores envolvidos, decisões necessárias, evidências usadas e critérios de acompanhamento. Essa estrutura torna implementação e avaliação de políticas mais fácil de estudar e aplicar.$$),
($$Políticas Públicas Educacionais$$,$$Implementação e avaliação de políticas$$,10,$$Para revisar, tente explicar implementação e avaliação de políticas sem consultar o material e depois dê um exemplo de situação escolar em que presumir que uma política produz os mesmos resultados em todos os contextos. Se a explicação depender apenas de palavras-chave, retome os conceitos e suas relações.$$),
($$Políticas Públicas Educacionais$$,$$Participação social e controle público$$,1,$$O ponto central de participação social e controle público é usar informação pública para acompanhar decisões e resultados educacionais. A compreensão começa por reconhecer quais decisões, relações e evidências fazem esse tema funcionar no cotidiano educacional.$$),
($$Políticas Públicas Educacionais$$,$$Participação social e controle público$$,2,$$Esse tema ganha sentido quando observado no contexto da escola e das políticas educacionais. Aqui, vale perguntar como confundir participação social com divulgação unilateral de decisões já tomadas aparece em situações concretas e quem participa das decisões.$$),
($$Políticas Públicas Educacionais$$,$$Participação social e controle público$$,3,$$Os conceitos principais precisam ser relacionados entre si. Em participação social e controle público, isso significa analisar a relação entre objetivos educacionais, responsabilidades, práticas profissionais e condições institucionais.$$),
($$Políticas Públicas Educacionais$$,$$Participação social e controle público$$,4,$$Um exemplo ajuda a visualizar a ideia: imagine uma escola diante de um problema de aprendizagem ou organização. A resposta precisa considerar confundir participação social com divulgação unilateral de decisões já tomadas, e não apenas uma ação isolada de um único profissional.$$),
($$Políticas Públicas Educacionais$$,$$Participação social e controle público$$,5,$$Na análise de uma situação real, procure identificar atores, responsabilidades, recursos, informações disponíveis e efeitos das decisões. Esse olhar evita conclusões rápidas sobre participação social e controle público.$$),
($$Políticas Públicas Educacionais$$,$$Participação social e controle público$$,6,$$Um erro frequente é undefined. Quando isso acontece, o conceito perde sua função analítica e a prática passa a responder mais a rotinas ou aparências do que às finalidades educacionais.$$),
($$Políticas Públicas Educacionais$$,$$Participação social e controle público$$,7,$$O aprofundamento pede atenção às relações entre norma, planejamento, prática e acompanhamento. Nenhuma dessas dimensões explica sozinha participação social e controle público; o sentido aparece na articulação entre elas.$$),
($$Políticas Públicas Educacionais$$,$$Participação social e controle público$$,8,$$Na prática pedagógica, uma boa aplicação é transformar o conceito em procedimento observável: definir uma questão, reunir evidências, discutir alternativas, decidir responsabilidades e acompanhar o que mudou depois da ação.$$),
($$Políticas Públicas Educacionais$$,$$Participação social e controle público$$,9,$$A síntese pode ser feita em uma sequência: finalidade educativa, atores envolvidos, decisões necessárias, evidências usadas e critérios de acompanhamento. Essa estrutura torna participação social e controle público mais fácil de estudar e aplicar.$$),
($$Políticas Públicas Educacionais$$,$$Participação social e controle público$$,10,$$Para revisar, tente explicar participação social e controle público sem consultar o material e depois dê um exemplo de situação escolar em que confundir participação social com divulgação unilateral de decisões já tomadas. Se a explicação depender apenas de palavras-chave, retome os conceitos e suas relações.$$)
) v(discipline,topic,position,content)
join public.disciplines d on d.name=v.discipline
join public.topics t on t.discipline_id=d.id and t.name=v.topic
join public.materials m on m.topic_id=t.id
where ms.material_id=m.id and ms.position=v.position;

insert into public.material_citations(material_id,source_id,citation_label)
select m.id,s.id,x.label
from (values
 ('Gestão Escolar','Lei nº 9.394/1996 — Lei de Diretrizes e Bases da Educação Nacional','LDB — organização da educação'),
 ('Gestão Escolar','Base Nacional Comum Curricular — Educação Infantil e Ensino Fundamental','BNCC — currículo e aprendizagens'),
 ('Gestão Escolar','Gestão Escolar - Concepções de gestão - Parte 1','UNIVESP — Gestão Escolar'),
 ('Coordenação Pedagógica','Resolução CNE/CP nº 1, de 15 de maio de 2006 — Diretrizes Curriculares Nacionais para o Curso de Graduação em Pedagogia','DCN Pedagogia'),
 ('Coordenação Pedagógica','Base Nacional Comum Curricular — Educação Infantil e Ensino Fundamental','BNCC — currículo'),
 ('Legislação e Organização da Educação Brasileira','Lei nº 9.394/1996 — Lei de Diretrizes e Bases da Educação Nacional','LDB'),
 ('Legislação e Organização da Educação Brasileira','Base Nacional Comum Curricular — Educação Infantil e Ensino Fundamental','BNCC'),
 ('Legislação e Organização da Educação Brasileira','Resolução CNE/CP nº 4, de 29 de maio de 2024 — Diretrizes Curriculares Nacionais para a Formação Inicial','CNE — Formação Inicial 2024'),
 ('Políticas Públicas Educacionais','Lei nº 9.394/1996 — Lei de Diretrizes e Bases da Educação Nacional','LDB — política e organização'),
 ('Políticas Públicas Educacionais','Sistema de Avaliação da Educação Básica — Saeb','Inep — Saeb'),
 ('Políticas Públicas Educacionais','Censo Escolar da Educação Básica','Inep — Censo Escolar')
) x(discipline,source_title,label)
join public.disciplines d on d.name=x.discipline
join public.topics t on t.discipline_id=d.id
join public.materials m on m.topic_id=t.id
join public.sources s on s.title=x.source_title
where not exists(select 1 from public.material_citations mc where mc.material_id=m.id and mc.source_id=s.id);